export type SupportedLanguage =
  | "fr" // Français (Défaut)
  | "en" // English
  | "fon" // Fongbé (Bénin)
  | "yo" // Yorùbá (Bénin)
  | "diu" // Dioula (Côte d'Ivoire & Burkina Faso)
  | "ba" // Baoulé (Côte d'Ivoire)
  | "wo" // Wolof (Sénégal)
  | "ff" // Pulaar / Peul (Sénégal)
  | "ee" // Éwé (Togo)
  | "kbp" // Kabyè (Togo)
  | "mos" // Mooré (Burkina Faso)
  | "dua"; // Douala (Cameroun)

export interface LanguageInfo {
  code: SupportedLanguage;
  name: string;
  nativeName: string;
  flag: string;
  country: string;
  category: "international" | "local";
}

