    sup_faq_subheading: "Fast answers to common questions about FCFA invoicing and compliance.",
    sup_faq_q1: "How is the 18% VAT calculated in the application?",
    sup_faq_a1: "VAT is automatically calculated at the statutory rate of 18% on the net subtotal (HT) according to the tax regulations of WAEMU countries (Benin, Côte d'Ivoire, Senegal, Togo, Burkina Faso, Mali, Niger). All amounts are strictly rounded to whole FCFA without cents.",
    sup_faq_q2: "How do I share an invoice directly via WhatsApp?",
    sup_faq_a2: "From the invoice list, click on the desired invoice to open its details. Then click the green 'WhatsApp' button: a customized message is prepared with the invoice number, FCFA amount, and secure public link for your customer.",
    sup_faq_q3: "How do I update my company details (TIN, RCCM)?",
