    sup_faq_heading: "Questions fréquentes (FAQ)",
    sup_faq_subheading: "Réponses rapides aux interrogations courantes sur la facturation FCFA.",
    sup_faq_q1: "Comment est calculée la TVA à 18 % dans l'application ?",
    sup_faq_a1: "La TVA est automatiquement calculée au taux réglementaire de 18 % sur le sous-total hors taxes (HT) conformément au code général des impôts des pays de l'UEMOA (Bénin, Côte d'Ivoire, Sénégal, Togo, Burkina Faso, Mali, Niger). Tous les montants sont strictement arrondis au franc CFA entier sans centimes.",
    sup_faq_q2: "Comment partager une facture directement par WhatsApp ?",
    sup_faq_a2: "Depuis la liste des factures, cliquez sur la facture désirée pour ouvrir sa fiche détaillée. Cliquez ensuite sur le bouton vert 'WhatsApp' : un message personnalisé est automatiquement préparé avec le numéro de facture, le montant en FCFA et le lien public sécurisé pour votre client.",
    sup_faq_q3: "Comment modifier les informations de mon entreprise (IFU, RCCM) ?",
    sup_faq_a3: "Dans le menu principal, cliquez sur 'Paramètres'. Dans le premier onglet 'Entreprise & Coordonnées', vous pouvez mettre à jour votre raison sociale, numéro IFU, RCCM, adresse et téléphone. Cliquez sur 'Enregistrer les coordonnées' : les modifications sont immédiatement appliquées à vos futures factures.",
    sup_faq_q4: "Quels modes de règlement Mobile Money sont pris en charge ?",
    sup_faq_a4: "DANHOMEY Facture intègre Wave Business, MTN Mobile Money, Moov Money, Orange Money, ainsi que les virements bancaires (RIB/IBAN), chèques et règlements en espèces. Vous pouvez enregistrer des paiements partiels ou complets en quelques clics.",
    sup_faq_q5: "Nos factures sont-elles conformes aux normes OHADA ?",
    sup_faq_a5: "Oui. Les mentions obligatoires du SYSCOHADA révisé (IFU, RCCM, conversion automatique du montant en toutes lettres, dates d'émission et d'échéance, détails des lignes) sont générées et validées sur chaque document.",
